window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[72]={"id":"072","numero":72,"titre":"Troubles à symptomatologie somatique et apparentés (TSSA)","objectifs":[{"id":"72-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition générale des troubles à symptomatologie somatique et apparentés","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">Troubles à symptomatologie somatique et apparentés (TSSA)</span> sont un cadre nosographique introduit par le <strong>DSM-5</strong> en remplacement des <em>« troubles somatoformes »</em> du DSM-IV. La nouveauté centrale est un <strong>décentrage</strong> : la sémiologie n'est plus définie négativement (« symptômes médicalement inexpliqués ») mais positivement par la <span class=\"kw-clinique\">triade pensées / émotions / comportements</span> qui accompagnent les manifestations physiques.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Critère décisif.</strong> <span class=\"kw-def\">Absence de maladie non psychiatrique pouvant expliquer les symptômes physiques n'est PAS un critère nécessaire</span> ⭐. <span class=\"kw-clinique\">Les</span> TSSA sont <span class=\"kw-clinique\">volontiers comorbides</span> d'un trouble médical non psychiatrique, et un trouble médical peut <strong>favoriser</strong> un TSSA en focalisant l'attention du patient sur certaines sensations corporelles (ex. fibromyalgie + rhumatisme <span class=\"kw-etio\">inflammatoire</span>, SII + <span class=\"kw-def\">MICI</span>, crises non épileptiques + <span class=\"kw-def\">épilepsie</span>).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Les</span> 4 entités du DSM-5</h4>\n      <table >\n        <thead><tr><th>Entité DSM-5</th><th>Définition synthétique</th><th>Équivalent DSM-IV</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Trouble à symptomatologie somatique (TSS)</strong></span></td>\n            <td>Pensées (anticipation catastrophique), <span class=\"kw-clinique\">émotions anxieuses</span> (soucis santé), comportements (consultations répétées) <strong>au sujet de signes/symptômes physiques mésinterprétés comme grave</strong>. Spécifier <em>« avec douleur prédominante »</em> si applicable.</td>\n            <td>Regroupe somatisation, trouble douloureux, somatoforme indifférencié, hypocondrie <strong>avec</strong> symptômes physiques pénibles</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Crainte excessive d'avoir une maladie</strong></span></td>\n            <td>Manifestations du TSS (pensées + émotions anxieuses + comportements) <strong>en l'absence</strong> de symptômes physiques pénibles ou invalidants par eux-mêmes. Durée <span class=\"kw-chiffre\">&gt; 6 mois</span>, tentatives de réassurance médicale inefficaces.</td>\n            <td>Hypocondrie <strong>sans</strong> symptômes physiques pénibles</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Trouble de conversion</strong></span> (= <em>trouble à symptomatologie neurologique fonctionnelle</em>)</td>\n            <td>Déficits moteurs ou sensoriels <span class=\"kw-clinique\">incompatibles avec la systématisation du système nerveux</span>, mais suggérant un trouble neurologique. Mécanismes de <span class=\"kw-def\">dissociation</span> souvent associés.</td>\n            <td>Dénomination inchangée (DSM-IV → DSM-5)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Autres TSSA spécifiés</strong></span></td>\n            <td>Regroupe <span class=\"kw-clinique\">les</span> <strong>syndromes somatiques fonctionnels</strong> (SII, fibromyalgie, <span class=\"kw-clinique\">syndrome de fatigue</span> chronique, syndrome d'hyperventilation, précordialgies à coronaires saines…).</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Définition alternative — CIM-11 : Syndrome de <span class=\"kw-alerte\">détresse</span> corporelle</h4>\n      <p>La CIM-11 a retenu une <strong>entité unique</strong> : le <span class=\"kw-def\">syndrome de détresse corporelle</span> (<em>Bodily distress syndrome</em>), défini par :</p>\n      <ul>\n        <li><strong><span class=\"kw-chiffre\">≥ 3</span> symptômes</strong> appartenant à <strong>≥ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>roupe</strong> parmi <span class=\"kw-clinique\">les</span> 4 ci-dessous,</li>\n        <li>entraînant un <span class=\"kw-alerte\">handicap significatif</span>,</li>\n        <li><span class=\"kw-clinique\">les</span> diagnostics différentiels pertinents ayant été écartés.</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Groupe de symptômes</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Tension musculo-squelettique</strong></td><td>Douleurs aux bras/jambes, douleurs musculaires, articulaires, dorsales, douleurs « migratrices », sensations de parésie ou faiblesse localisée, engourdissement, picotements désagréables</td></tr>\n          <tr><td><strong>Symptômes généraux</strong></td><td>Fatigue excessive, troubles de la concentration, altération de la mémoire, <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">vertiges</span></td></tr>\n          <tr><td><strong>Activation neurovégétative cardiovasculaire</strong></td><td><span class=\"kw-clinique\">Palpitations</span>, éréthisme cardiaque, <span class=\"kw-clinique\">précordialgie</span>, <span class=\"kw-clinique\">dyspnée</span> sans effort, hyperventilation, <span class=\"kw-clinique\">sueurs</span>, bouche sèche</td></tr>\n          <tr><td><strong>Activation gastro-intestinale</strong></td><td><span class=\"kw-clinique\">Douleurs abdominales</span>, troubles du transit (selles molles et fréquentes), ballonnements/gaz/distension, <span class=\"kw-clinique\">régurgitations</span>, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">nausées</span>, brûlures ép<span class=\"kw-chiffre\">iga</span>striques</td></tr>\n        </tbody>\n      </table>\n      <p><em>La sévérité du syndrome est déterminée par le <strong>nombre d'organes</strong> présentant certains de ces symptômes.</em></p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Définition par spécialité — Syndromes somatiques fonctionnels</h4>\n      <p><span class=\"kw-clinique\">Les</span> spécialités non psychiatriques utilisent rarement la catégorie « TSSA » et préfèrent la notion de <span class=\"kw-def\">syndrome somatique fonctionnel</span> (un seul domaine corporel). En réalité ces syndromes sont souvent <strong>comorbides entre eux</strong> et sans <span class=\"kw-def\">physiopathologie</span> spécifique.</p>\n\n      <table >\n        <thead><tr><th>Spécialité</th><th>Syndrome somatique fonctionnel</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Gastroentérologie</strong></td><td><span class=\"kw-clinique\">Syndrome de l</span>'intestin irritable (SII) ; dyspepsie non ulcéreuse</td></tr>\n          <tr><td><strong>Rhumatologie</strong></td><td>Fibromyalgie (= syndrome polyalgique idiopathique diffus, <span class=\"kw-def\">SPID</span>)</td></tr>\n          <tr><td><strong>Gynécologie</strong></td><td>Syndrome prémenstruel ; algies pelviennes chroniques ; vulvodynies</td></tr>\n          <tr><td><strong>Neurologie</strong></td><td><span class=\"kw-clinique\">Céphalées</span> de tension</td></tr>\n          <tr><td><strong>Cardiologie</strong></td><td>Précordialgies à coronaires saines</td></tr>\n          <tr><td><strong>Pneumologie</strong></td><td>Syndrome d'hyperventilation</td></tr>\n          <tr><td><strong>Immunologie</strong></td><td><span class=\"kw-clinique\">Syndrome de fatigue</span> chronique</td></tr>\n          <tr><td><strong>ORL</strong></td><td>Rhinite chronique non <span class=\"kw-etio\">allergique</span></td></tr>\n          <tr><td><strong>Stomatologie / CMF</strong></td><td>Syndrome algodysfonctionnel de l'appareil manducateur (<span class=\"kw-def\">SADAM</span>) ; glossodynies</td></tr>\n          <tr><td><strong>Allergologie</strong></td><td><span class=\"kw-ci\">Intolérance</span> environnementale idiopathique (IEI)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Cas particulier — <span class=\"kw-ci\">Intolérance</span> environnementale idiopathique (IEI).</strong> Ces syndromes (<em>« sensibilité chimique multiple »</em>, <em>« électrosensibilité »</em>) sont caractérisés non pas par des symptômes spécifiques, mais par leur <span class=\"kw-clinique\">attribution rétrospective</span> à une exposition (produit chimique, champs électromagnétiques…), rarement à un niveau de nocivité avéré. Caractère non mesurable de l'exposition, perception subjective accrue pouvant évoluer (ex. intolérance à la moindre odeur sans trouble olfactif objectif).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble anxieux · 71 — Troubles conduite alimentaire · 73 — Techniques psychothérapeutiques</em></p>","frequence":4},{"id":"72-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de ce que ne sont pas les troubles à symptomatologie somatique et apparentés","contenu":"<p>Plusieurs entités <strong>ressemblent</strong> aux TSSA mais en sont distinctes par leur <span class=\"kw-def\">physiopathologie</span> et leur prise en charge. Certaines sont incluses dans la <em>section</em> DSM-5 sur <span class=\"kw-clinique\">les</span> TSSA (par voisinage clinique) sans en être à proprement parler, d'autres sont classées ailleurs.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Inclus dans la section DSM-5 « TSSA » mais NE sont PAS des TSSA</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th><th>Discriminant clé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Trouble factice</strong></span> (= <span class=\"kw-clinique\">syndrome de Münchhausen</span>)</td>\n            <td>\n              <strong>Production intentionnelle</strong> de signes ou symptômes physiques ou psychologiques, <span class=\"kw-alerte\">sans motivation externe évidente</span> :<br>\n              <strong>Modalités :</strong> exagération/invention de symptômes ; falsification de documents médicaux ; ingestion de toxiques ; inoculation volontaire de germes pathogènes (ex. injection IV de salive/selles).<br>\n              <strong>Variante :</strong> trouble factice <em>par procuration</em> — imposé à autrui (ex. parent qui rend malade son enfant avec des médicaments, ou colore <span class=\"kw-clinique\">les</span> urines avec du sang).\n            </td>\n            <td><span class=\"kw-clinique\">Production intentionnelle</span> sans bénéfice externe</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Facteurs psychologiques influençant une autre affection médicale</strong></span> (autrefois <em>« troubles psycho-somatiques »</em>)</td>\n            <td>Pathologie médicale non psychiatrique <span class=\"kw-clinique\">avec lésion identifiable</span>, pour laquelle des facteurs psychologiques (surtout <strong>stress</strong>) jouent un rôle prépondérant de <strong>facteur déclenchant ou entretenant</strong>. Ex. maladie coronarienne dont le stress est un FdR indépendant.</td>\n            <td><span class=\"kw-clinique\">Lésion</span> organique <strong>présente</strong>, le psychologique entretient</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Non inclus dans la section DSM-5 « TSSA »</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th><th>Discriminant clé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Simulation</strong></span></td>\n            <td>Production <span class=\"kw-clinique\">intentionnelle</span> de signes/symptômes <strong>avec motivation consciente externe</strong> : échapper à des poursuites judiciaires, obtenir des drogues illicites, des indemnités, une pension de retraite, un arrêt de travail…</td>\n            <td>Intentionnelle <strong>+ bénéfice externe explicite</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Peur d'une dysmorphie corporelle</strong></span> (= dysmorphophobie)</td>\n            <td>\n              Classée dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">troubles obsessionnels-compulsifs</span> du DSM-5 :<br>\n              <strong>Idées obsessionnelles :</strong> imperfection ou défauts dans l'apparence physique ;<br>\n              <strong>Compulsions :</strong> vérifications devant un miroir, toilette interminable, arrachage de poils…<br>\n              <strong>DD :</strong> trouble entraînant des stratégies de contrôle de poids → <span class=\"kw-clinique\">anorexie mentale</span>.\n            </td>\n            <td>Classée TOC (pas TSSA)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège EDN classique.</strong> Ne pas confondre <span class=\"kw-def\">trouble factice</span> (production intentionnelle, motivation INTERNE inconsciente) et <span class=\"kw-def\">simulation</span> (production intentionnelle, motivation EXTERNE consciente). La <strong>nature de la motivation</strong> est le discriminant clé.\n      </div>","frequence":1},{"id":"72-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence générale","contenu":"<table >\n        <thead><tr><th>Population</th><th><span class=\"kw-def\">Prévalence</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Adulte</strong></td><td><span class=\"kw-chiffre\">5 - 10 %</span></td></tr>\n          <tr><td><strong>Enfant</strong></td><td><span class=\"kw-chiffre\">12 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Lieu de rencontre.</strong> <span class=\"kw-clinique\">Les</span> TSSA sont <span class=\"kw-clinique\">essentiellement rencontrés dans les consultations médicales non psychiatriques</span> — ils représentent l'<strong>une des 1ères causes de consultation toutes spécialités confondues</strong>. C'est dire l'importance que le médecin généraliste et tous les spécialistes d'organe sachent les reconnaître et les prendre en charge.\n      </div>\n\n      <p><strong>Caractéristiques transversales :</strong></p>\n      <ul>\n        <li>Prépondérance de symptômes physiques <span class=\"kw-clinique\">chroniques, pénibles et invalidants</span>, souvent sans anomalie au niveau des organes désignés ;</li>\n        <li>Associés à des <strong>pensées, émotions et comportements</strong> pouvant être jugés comme excessifs ou inappropriés.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Enjeu majeur.</strong> L'absence de cause organique identifiable fait <span class=\"kw-alerte\">sous-estimer leur retentissement voire leur existence</span>. Pourtant : impact majeur sur qualité de vie et fonctionnement du sujet ; mécanismes accessibles à la thérapeutique. À considérer comme des troubles à part entière.\n      </div>","frequence":1},{"id":"72-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence des principaux troubles","contenu":"<table >\n        <thead><tr><th>Trouble DSM-5</th><th><span class=\"kw-def\">Prévalence</span></th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Trouble à symptomatologie somatique (TSS)</strong></span></td>\n            <td><span class=\"kw-chiffre\">5 - 7 %</span></td>\n            <td>Le plus fréquent du groupe — entité « pivot »</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Crainte excessive d'avoir une maladie</strong></span></td>\n            <td><span class=\"kw-chiffre\">3 - 8 %</span></td>\n            <td>Ancienne hypochondrie <em>sans</em> symptômes physiques pénibles</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Trouble de conversion</strong></span> (= trouble à symptomatologie neurologique fonctionnelle)</td>\n            <td><span class=\"kw-chiffre\">0,1 %</span> (population générale)<br><span class=\"kw-chiffre\">5 %</span> des consultations en <strong>neurologie</strong></td>\n            <td>Rare en population générale, surreprésenté en neurologie</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"72-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs prédisposants, précipitants et de maintien ou d’aggravation","contenu":"<div class=\"callout callout-info\">\n        <strong>Modèle biopsychosocial.</strong> L'intérêt du DSM-5 a été de <span class=\"kw-def\">recentrer la sémiologie sur la manière dont les manifestations physiques sont vécues, exprimées, gérées par le patient</span>, en lien avec des mécanismes <strong>biologiques</strong> (ex. sensibilisation centrale dans <span class=\"kw-clinique\">les</span> troubles douloureux), <strong>psychologiques</strong> (ex. conditionnement) et <strong>sociaux</strong> (ex. organisation de l'offre de soins). On distingue clairement ce qui peut <em>favoriser</em> (perfectionnisme), <em>déclencher</em> (épisode <span class=\"kw-etio\">infectieux</span> aigu) ou <em>pérenniser</em> (conduites d'évitement) les troubles.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Facteurs déclenchants (= précipitants)</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Facteurs physiques ++</strong></span></td>\n            <td>Volontiers physiques : épisode <strong><span class=\"kw-etio\">infectieux</span></strong>, <strong>traumatisme</strong> physique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>⚠ Ne PAS focaliser sur les facteurs psychologiques</strong></span></td>\n            <td>\n              Ne pas chercher activement un événement de vie stressant qui « expliquerait » <span class=\"kw-clinique\">les</span> symptômes :<br>\n              <strong>Absence de spécificité :</strong> présence de FR psychologiques de stress n'est ni sensible ni spécifique ;<br>\n              <strong>Risque relationnel :</strong> patients peuvent se montrer réticents à livrer des éléments si une hypothèse psychologique est formulée → <span class=\"kw-alerte\">rupture</span> de l'alliance.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · Mécanismes cognitifs (= FR de maintien / aggravation)</h4>\n      <ul>\n        <li><span class=\"kw-def\"><strong>Attention excessive aux sensations viscérales et somatiques</strong></span> — avec vérifications corporelles excessives.</li>\n        <li><span class=\"kw-def\"><strong>Attribution d'une signification menaçante</strong></span> à ces sensations — ± interprétations catastrophiques (<span class=\"kw-clinique\">catastrophisme</span>).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3 · Mécanismes comportementaux (renforcent <span class=\"kw-clinique\">les</span> symptômes — FR de maintien / aggravation)</h4>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Conditionnement opérant</strong></span> (skinnerien)</td>\n            <td>\n              <strong>1.</strong> Un stimulus conditionnel acquiert une dimension pénible par association avec un stimulus inconditionnel (ex. <em>distension du tube digestif</em> devient douloureuse par association à une <em>gastroentérite aiguë</em>).<br>\n              <strong>2.</strong> Le stimulus conditionnel entraîne ensuite des symptômes pénibles <strong>même sans</strong> stimulus inconditionnel.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Évitement</strong></span></td>\n            <td>L'évitement des symptômes physiques empêche l'<span class=\"kw-clinique\">extinction du conditionnement répondant initial</span>. Ex. <span class=\"kw-clinique\">syndrome de fatigue</span> chronique : <span class=\"kw-clinique\">les</span> patients évitent l'effort physique de peur d'augmenter leur fatigue à court terme → renforcent par conditionnement opérant leur fat<span class=\"kw-chiffre\">iga</span>bilité à long terme.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">4 · Mécanismes sociaux (renforcent <span class=\"kw-clinique\">les</span> symptômes — FR de maintien / aggravation)</h4>\n      <ul>\n        <li>Obtention d'un <span class=\"kw-clinique\">statut de malade</span> ;</li>\n        <li>Attention d'autrui induite par <span class=\"kw-clinique\">les</span> symptômes somatiques (« bénéfices secondaires »).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">5 · Facteurs prédisposants (favorisants)</h4>\n      <table >\n        <thead><tr><th>Population</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td>\n              <strong>ATCD familiaux :</strong> ATCD familiaux de TSSA ;<br>\n              <strong>Stress :</strong> facteurs de stress chroniques, stratégies d'ajustement au stress réduites (ex. troubles de la personnalité, troubles anxieux) ;<br>\n              <strong>Personnalité :</strong> dimension anxieuse (<span class=\"kw-def\">névrosisme</span>) ;<br>\n              <strong>Antécédent médical :</strong> exposition récente ou ancienne à une maladie non psychiatrique ;<br>\n              <strong>Alexithymie :</strong> difficulté à identifier, différencier et exprimer ses émotions (ou celles d'autrui) — difficulté à différencier son état émotionnel des sensations corporelles ;<br>\n              <strong>Réactivité physiologique :</strong> réactivité au stress excessive pouvant donner lieu à des interprétations inquiétantes.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td>\n              <strong>Famille :</strong> ATCD familiaux, stratégies d'ajustement au stress provenant de la famille (= réponse de la famille aux symptômes) ;<br>\n              <strong>Stress :</strong> facteurs de stress ;<br>\n              <strong><span class=\"kw-def\">Comorbidités</span> psychiatriques :</strong> anxio-dépressives <span class=\"kw-clinique\">les</span> plus fréquentes, certaines dimensions de personnalité ;<br>\n              <strong>Santé globale :</strong> problèmes de santé plus généraux.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Implication thérapeutique majeure ⭐.</strong> La proposition au patient d'un <span class=\"kw-def\">modèle explicatif</span>, même schématique, des troubles dont il souffre et <strong>compatible avec la description qu'il en a faite</strong>, constitue un axe fondamental de la prise en charge. C'est ce modèle qui crédibilise <span class=\"kw-clinique\">les</span> propositions thérapeutiques ultérieures.\n      </div>","frequence":1},{"id":"72-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie des principaux troubles","contenu":"<p>La démarche est <strong>positive</strong> (reconnaître <span class=\"kw-clinique\">les</span> manifestations pensées/émotions/comportements associées aux symptômes physiques), pas négative (« on n'a rien trouvé »). <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes entités à savoir reconnaître.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Trouble à symptomatologie somatique (TSS) — <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">5-7 %</span></h4>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Pensées</strong></span> — anticipation des conséquences interprétées comme potentiellement catastrophiques ;</li>\n        <li><span class=\"kw-clinique\"><strong>Émotions anxieuses</strong></span> — soucis, préoccupations, inquiétudes sur la santé ;</li>\n        <li><span class=\"kw-clinique\"><strong>Comportements</strong></span> — consultations médicales répétées, vérifications corporelles, recherche d'information…</li>\n        <li><strong>Cible :</strong> au sujet de <span class=\"kw-clinique\">signes / symptômes physiques mésinterprétés comme une pathologie grave</span>.</li>\n      </ul>\n      <p><strong>Spécificateur :</strong> à préciser si TSS <span class=\"kw-def\">« avec douleur prédominante »</span> (ancien « trouble douloureux chronique » du DSM-IV).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · Crainte excessive d'avoir une maladie — <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">3-8 %</span></h4>\n      <ul>\n        <li>Manifestations du TSS (pensées + émotions anxieuses + comportements) ;</li>\n        <li><strong>Mais en l'absence</strong> de signes / symptômes physiques pénibles ou invalidants par eux-mêmes ;</li>\n        <li>Durée <span class=\"kw-chiffre\">&gt; 6 mois</span> ;</li>\n        <li>Tentatives de réassurance médicale <span class=\"kw-clinique\">inefficaces</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3 · Trouble de conversion (= trouble à symptomatologie neurologique fonctionnelle) — <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">0,1 %</span></h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"kw-clinique\">Déficits moteurs ou sensoriels</span> incompatibles avec la systématisation du système nerveux, mais suggérant la présence d'un trouble neurologique ou d'un autre trouble médical.</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs de stress</strong></td>\n            <td>Peuvent être retrouvés mais <span class=\"kw-alerte\">pas nécessairement</span> — leur absence n'élimine pas le diagnostic.</td>\n          </tr>\n          <tr>\n            <td><strong>Triade pensées / émotions / comportements</strong></td>\n            <td><span class=\"kw-clinique\">Moins présente</span> que dans <span class=\"kw-clinique\">les</span> autres TSSA.</td>\n          </tr>\n          <tr>\n            <td><strong>Mécanismes de dissociation</strong></td>\n            <td>\n              Souvent associés (plus que <span class=\"kw-clinique\">les</span> cognitions/émotions/comportements). Impliqués dans la <span class=\"kw-def\">physiopathologie</span> mais <strong>pas <span class=\"kw-def\">critères de</span> définition</strong>. Manifestations :<br>\n              <span class=\"kw-clinique\">Amnésie dissociative</span> ;<br>\n              <span class=\"kw-clinique\">Symptômes de déréalisation / dépersonnalisation</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Explorations</strong></td>\n            <td>\n              <strong>Examen neurologique :</strong> permet d'indiquer l'incompatibilité de la sémiologie avec une maladie neurologique ;<br>\n              <strong><span class=\"kw-imagerie\">EEG</span> (crises non épileptiques psychogènes) :</strong> montre l'absence d'activité épileptiforme pendant la symptomatologie — <span class=\"kw-clinique\">nécessaire au diagnostic</span> mais n'exclut pas une <span class=\"kw-alerte\">comorbidité épileptique</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Diagnostics différentiels à éliminer</h4>\n      <table >\n        <thead><tr><th>Famille de DD</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pathologie médicale non psychiatrique</strong></td>\n            <td>À éliminer selon la clinique, <span class=\"kw-alerte\">sans multiplier les examens</span>. <span class=\"kw-def\">Comorbidité</span> fréquente — à ne pas sous-évaluer.</td>\n          </tr>\n          <tr>\n            <td><strong>Troubles anxieux</strong></td>\n            <td>Manifestations neurovégétatives de l'anxiété (<em>troubles paniques ++</em>) → plaintes somatiques fréquentes</td>\n          </tr>\n          <tr>\n            <td><strong>Troubles psychotiques</strong></td>\n            <td>Sensations corporelles <span class=\"kw-clinique\">hallucinatoires</span> et idées délirantes hypocondriaques</td>\n          </tr>\n          <tr>\n            <td><strong>Trouble dépressif caractérisé (EDC)</strong></td>\n            <td>Plaintes douloureuses non systématisées. Discriminant clé EDC <span class=\"kw-bio\">vs</span> TSSA ⭐ : <span class=\"kw-clinique\">la douleur disparaît avec le syndrome dépressif dans l'EDC</span> (donc évolue parallèlement à l'humeur).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Comorbidités</span> à rechercher systématiquement.</strong> <strong>Psychiatriques :</strong> EDC, troubles anxieux, troubles de la personnalité. <strong>Non psychiatriques :</strong> pathologie médicale non psychiatrique fréquemment associée ⭐ — à ne pas sous-évaluer (fibromyalgie + <span class=\"kw-clinique\">PR</span>, SII + <span class=\"kw-def\">MICI</span>, crises non épileptiques + <span class=\"kw-def\">épilepsie</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble anxieux · 105 — Epilepsie · 284 — <span class=\"kw-clinique\">Syndrome de l</span>'intestin irritable (SII)</em></p>","frequence":1},{"id":"72-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif prioritaire ⭐⭐⭐.</strong> <span class=\"kw-def\">Maintenir une alliance thérapeutique de qualité</span>. C'est l'axe central, sans quoi rien n'est possible chez ces patients souvent sceptiques voire réticents à l'idée d'une participation psychologique à leurs symptômes.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Orientation initiale</h4>\n      <ul>\n        <li><strong>Ambulatoire :</strong> prise en charge essentiellement ambulatoire, coordonnée par un <span class=\"kw-def\">médecin référent</span>.</li>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> en général <span class=\"kw-clinique\">non nécessaire</span>. Indications ciblées :\n          <ul>\n            <li><strong>Médecine courte :</strong> pour éliminer un <span class=\"kw-def\">diagnostic différentiel</span> de pathologie médicale non psychiatrique ;</li>\n            <li><strong>Psychiatrie :</strong> en cas de <span class=\"kw-def\">comorbidité</span> psychiatrique avec <span class=\"kw-alerte\">signes de gravité</span> ;</li>\n            <li><strong>Pédopsychiatrie :</strong> exploration médicale ciblée + PEC pédopsy avec recherche des <span class=\"kw-def\">comorbidités</span> et limitation des bénéfices secondaires.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · Stratégies de communication du diagnostic (<span class=\"kw-clinique\">les</span> 3 piliers ⭐)</h4>\n      <table >\n        <thead><tr><th>Pilier</th><th>Mise en œuvre</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>① Reconnaître les symptômes comme « véritables »</strong></span></td>\n            <td>\n              Reconnaître la pénibilité, le retentissement, le caractère <span class=\"kw-clinique\">non volontaire</span> des troubles. Ne pas disqualifier le parcours antérieur (médecine conventionnelle ou pratiques alternatives). Reconnaître explicitement l'errance diagnostique et le sentiment de ne pas être pris au sérieux.<br>\n              <span class=\"kw-alerte\">⚠ Ne jamais dire</span> : <em>« vous n'avez rien »</em>, <em>« c'est dans la tête »</em>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>② Proposer un diagnostic POSITIF</strong></span></td>\n            <td>\n              Terme <span class=\"kw-clinique\">« troubles fonctionnels »</span> souvent bien accepté. Expliquer qu'il s'agit d'une <strong>maladie commune et reconnue</strong>.<br>\n              <span class=\"kw-alerte\">⚠ Éviter le diagnostic par élimination</span> (<em>« <span class=\"kw-clinique\">les</span> examens n'ont rien trouvé, donc cela doit être... »</em>) qui discrédite le diagnostic et suggère une hiérarchie de valeurs au patient.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>③ Évoquer les facteurs déclenchants et de maintien</strong></span></td>\n            <td>\n              Exposer un <strong>modèle explicatif</strong> de survenue et de pérennisation des symptômes, même schématique. Objectif : crédibiliser <span class=\"kw-clinique\">les</span> propositions thérapeutiques et aider le patient à se les approprier. Ne pas récuser un diagnostic auquel le patient adhère (ex. fibromyalgie), sauf s'il implique sans fondement un agent causal externe (<em>« électrosensibilité »</em>, <em>« maladie de Lyme chronique »</em>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3 · Place des examens complémentaires</h4>\n      <p><strong>Objectif :</strong> éliminer une pathologie médicale non psychiatrique. Mais attention à la <span class=\"kw-alerte\">prescription excessive</span> qui pérennise le trouble :</p>\n      <ul>\n        <li>Risque de révélation d'<span class=\"kw-clinique\">incidentalomes</span> (explorations / traitements inutiles) ;</li>\n        <li>Renforcement de certaines représentations du patient ⭐ : <em>« <span class=\"kw-clinique\">les</span> médecins ne savent pas ce que j'ai »</em>, <em>« si on me prescrit cet examen, c'est que le médecin pense à un problème grave »</em>, <em>« un autre spécialiste pourrait peut-être me dire ce que j'ai »</em>, <em>« si on répète cet examen, c'est que les résultats du premier ne sont pas fiables »</em>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Question-clé du clinicien.</strong> <em>« Si le patient n'était pas si inquiet, est-ce que je prescrirais cet examen ? »</em> Si la réponse est non, ne pas le prescrire.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">4 · Traitements <span class=\"kw-etio\">médicamenteux</span></h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Indications / efficacité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Médicaments symptomatiques</strong></span> (<span class=\"kw-ttt\">antalgiques</span>, antispasmodiques)</td>\n            <td><span class=\"kw-alerte\">Inefficaces dans les TSSA</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>ISRS</strong></span></td>\n            <td>Efficacité <span class=\"kw-clinique\">modeste</span> dans : syndromes fonctionnels intestinaux, crainte excessive d'avoir une maladie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>IRSNA</strong></span></td>\n            <td>Peuvent soulager certains TSS avec <span class=\"kw-clinique\">douleur prédominante</span> (ex. fibromyalgie)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>⚠ Vigilance EI majeure.</strong> <span class=\"kw-alerte\">Propension accrue aux effets indésirables</span> chez <span class=\"kw-clinique\">les</span> patients souffrant de TSSA — débuter à faible posologie, <span class=\"kw-def\">éducation thérapeutique</span> renforcée, <span class=\"kw-def\">réévaluation</span> rapprochée.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">5 · Psychothérapie</h4>\n      <ul>\n        <li><span class=\"kw-def\"><strong>TCC (1ère intention)</strong></span> — efficacité démontrée dans de nombreux TSSA :\n          <ul>\n            <li><strong>Plan cognitif :</strong> prise de conscience de la <em>focalisation de l'attention</em> sur <span class=\"kw-clinique\">les</span> sensations corporelles et du <em>catastrophisme</em> ;</li>\n            <li><strong>Plan comportemental :</strong> identifier et <em>diminuer <span class=\"kw-clinique\">les</span> conduites d'évitement par l'exposition</em>.</li>\n          </ul>\n        </li>\n        <li><strong>Techniques complémentaires :</strong>\n          <ul>\n            <li>Entraînement attentionnel — thérapies basées sur la <span class=\"kw-clinique\">pleine conscience</span> ;</li>\n            <li>Approches psycho-corporelles — relaxation, sophrologie, <span class=\"kw-clinique\">hypnose</span>, méditation pleine conscience ;</li>\n            <li>Exercices de relaxation — respiratoires, baisse de la tension musculaire, <span class=\"kw-clinique\">biofeedback</span> ;</li>\n            <li><strong>Thérapie familiale</strong> chez l'<span class=\"kw-clinique\">enfant / adolescent</span> (facteur de stress souvent lié à la dynamique familiale).</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">6 · Activité physique</h4>\n      <p>Promotion essentielle dans <span class=\"kw-clinique\">les</span> tableaux dominés par la <span class=\"kw-clinique\">fatigue</span> et/ou la <span class=\"kw-clinique\">douleur</span> :</p>\n      <ul>\n        <li><strong>Modalités :</strong> en douceur mais avec régularité, malgré une motivation souvent médiocre des patients ;</li>\n        <li><strong><span class=\"kw-chiffre\">1ère intention</span> :</strong> <span class=\"kw-ttt\">Tai Chi</span> (efficacité démontrée dans plusieurs TSSA), Qi Gong, Yoga, Marche nordique, Natation.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">7 · Coordination du <span class=\"kw-def\">suivi</span></h4>\n      <ul>\n        <li><strong>Médecin référent</strong> indispensable pour limiter la répétition des examens complémentaires ;</li>\n        <li>Transmettre l'hypothèse diagnostique et <span class=\"kw-clinique\">les</span> préconisations à tous les intervenants dans un <strong>courrier synthétique</strong> ;</li>\n        <li>Expertise ponctuelle d'un spécialiste de l'appareil désigné ou d'un médecin <strong>interniste</strong> — peut permettre au référent de se dégager du <span class=\"kw-def\">diagnostic différentiel</span> pour se concentrer sur la thérapeutique ;</li>\n        <li><strong>Construction de l'alliance</strong> — négocier avec le patient <span class=\"kw-clinique\">les</span> <strong>objectifs ET les moyens</strong> de la thérapie ;</li>\n        <li><strong>Objectifs thérapeutiques modestes et atteignables</strong> — centrés chez l'adulte sur l'<em>atténuation des symptômes et de leur retentissement psychosocial</em> plutôt que sur la guérison (résolution complète parfois observée si trouble récent).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques · 74 — Psychotropes · 66 — Trouble anxieux</em></p>","frequence":6},{"id":"72-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les spécificités chez le sujet jeune","contenu":"<div class=\"callout callout-info\">\n        <strong>Principe central.</strong> Chez l'enfant, <span class=\"kw-def\">tenir compte des représentations de l'enfant lui-même MAIS AUSSI de celles des parents</span>. La famille doit être impliquée à <strong>chaque étape</strong> de l'évaluation et de la prise en charge.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Représentations familiales — pièges à anticiper</h4>\n      <ul>\n        <li>Familles qui <span class=\"kw-clinique\">attribuent les symptômes à une pathologie médicale non psychiatrique sous-jacente</span> et refusent l'hypothèse fonctionnelle ;</li>\n        <li>Familles qui expliquent <span class=\"kw-clinique\">les</span> symptômes par des <span class=\"kw-clinique\">représentations religieuses ou culturelles</span> ;</li>\n        <li>Stratégies parentales utilisées pour faire face et diminuer <span class=\"kw-clinique\">les</span> manifestations symptomatiques (à explorer, parfois contre-productives).</li>\n      </ul>\n      <p><strong>Implication clinique :</strong> tenir compte de ces représentations pour maintenir l'alliance thérapeutique et la qualité des soins. Le programme d'interventions auprès de l'enfant <strong>doit inclure la famille</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · PEC pédiatrique (médecine non psychiatrique)</h4>\n      <ul>\n        <li><strong>Exploration médicale</strong> pour éliminer <span class=\"kw-clinique\">les</span> principaux DD : examens complémentaires <span class=\"kw-clinique\">utiles et limités</span> ;</li>\n        <li>Rassurer l'enfant, l'adolescent et sa famille ;</li>\n        <li>Ouvrir sur la <strong>dimension psychologique</strong> sans la forcer.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3 · PEC pédopsychiatrique</h4>\n      <ul>\n        <li>Observation clinique + recherche des <span class=\"kw-clinique\">comorbidités psychiatriques</span> (anxio-dépressives <span class=\"kw-clinique\">les</span> plus fréquentes) ;</li>\n        <li>Mise en place d'une PEC adaptée en <strong>limitant <span class=\"kw-clinique\">les</span> facteurs de maintenance et les bénéfices secondaires</strong> ;</li>\n        <li><strong>Psychothérapies :</strong>\n          <ul>\n            <li><span class=\"kw-def\">TCC</span> — chez l'enfant et l'adolescent, ce sont <span class=\"kw-clinique\">les</span> <strong>interventions les plus évaluées</strong> avec un bon niveau d'efficacité ;</li>\n            <li><span class=\"kw-def\">Thérapie familiale</span> — facteur de stress souvent lié à la dynamique familiale ;</li>\n            <li><span class=\"kw-def\">Psychothérapie individuelle</span> avec approche psychopathologique et/ou cognitive et comportementale.</li>\n          </ul>\n        </li>\n        <li>Aider <span class=\"kw-clinique\">les</span> familles à <strong>communiquer sur les facteurs de stress</strong> de leur enfant et à y faire face.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Rappel épidémiologique.</strong> <span class=\"kw-def\">Prévalence</span> des TSSA chez l'<span class=\"kw-clinique\">enfant : 12 %</span> (<span class=\"kw-bio\">vs</span><span class=\"kw-chiffre\"> 5-10 %</span> chez l'adulte) — pas un trouble rare. À évoquer devant toute plainte somatique chronique inexpliquée chez un jeune.\n      </div>","frequence":2},{"id":"72-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications d’une évaluation psychiatrique","contenu":"<p>L'avis psychiatrique n'est <strong>pas systématique</strong> dans <span class=\"kw-clinique\">les</span> TSSA — la PEC initiale est en général assurée par le médecin référent (généraliste). 4 situations imposent ou recommandent une évaluation psychiatrique.</p>\n\n      <table >\n        <thead><tr><th>Indication</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>① Comorbidité psychiatrique suspectée</strong></span></td>\n            <td>\n              <strong><span class=\"kw-def\">Épisode dépressif caractérisé</span> (EDC)</strong> — DD parfois difficile, mais douleur disparaît avec le syndrome dépressif dans l'EDC ;<br>\n              <strong>Trouble anxieux caractérisé</strong> (notamment trouble panique) ;<br>\n              <strong>État de stress post-traumatique (ESPT)</strong> ;<br>\n              <strong>Trouble de la personnalité</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>② Signes de gravité</strong></span></td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span> en psychiatrie possible en cas de <span class=\"kw-def\">comorbidité</span> psychiatrique avec <strong><span class=\"kw-alerte\">signes de gravité</span></strong> (risque suicidaire, <span class=\"kw-alerte\">décompensation</span>, <span class=\"kw-alerte\">rupture</span> sociale majeure).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>③ TSSA chroniques ou réfractaires</strong></span></td>\n            <td>Préférable d'orienter vers un <strong>praticien expérimenté</strong> (psychiatre ou médecin formé à ces troubles) en cas d'échec de la prise en charge initiale ou de chronicisation prolongée.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>④ Difficulté diagnostique</strong></span></td>\n            <td>DD difficile avec un trouble psychotique (sensations corporelles hallucinatoires, idées délirantes hypocondriaques) — avis spécialisé pour préciser.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Ne pas confondre avec.</strong> L'<span class=\"kw-clinique\">expertise ponctuelle d'un spécialiste d'organe</span> (interniste, gastro, rhumato selon l'appareil désigné) reste utile pour <em>arbitrer la nécessité ou non de poursuivre <span class=\"kw-clinique\">les</span> explorations</em> — ce n'est PAS la même chose qu'un avis psychiatrique, ces 2 expertises peuvent se cumuler.\n      </div>","frequence":1},{"id":"72-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des thérapeutiques non médicamenteuses","contenu":"<p><span class=\"kw-clinique\">Les</span> thérapeutiques <strong>non médicamenteuses sont le pilier du traitement des TSSA</strong> (les médicaments symptomatiques sont inefficaces, les psychotropes ont une efficacité modeste). <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes familles à connaître.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Psychothérapies — TCC en <span class=\"kw-chiffre\">1ère intention</span></h4>\n      <table >\n        <thead><tr><th>Approche</th><th>Indications / objectifs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>TCC (1ère intention)</strong></span></td>\n            <td>\n              Efficacité démontrée dans de nombreux TSSA. Objectifs :<br>\n              <strong>Cognitif :</strong> prise de conscience de la focalisation de l'attention sur <span class=\"kw-clinique\">les</span> sensations corporelles, du catastrophisme ;<br>\n              <strong>Comportemental :</strong> identifier et diminuer les conduites d'évitement par l'exposition ; limitation progressive de l'évitement (coopération avec tous les professionnels impliqués).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Thérapies de pleine conscience</strong></span> (mindfulness)</td>\n            <td>Entraînement attentionnel — <span class=\"kw-bio\">complément</span> utile aux TCC</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Approches psycho-corporelles</strong></span></td>\n            <td>Relaxation, sophrologie, <strong>hypnose</strong>, méditation pleine conscience</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Exercices de relaxation</strong></span></td>\n            <td>Exercices respiratoires, baisse de la tension musculaire, <strong>biofeedback</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Thérapie familiale</strong></span></td>\n            <td>Indiquée chez l'<span class=\"kw-clinique\">enfant et l'adolescent</span> — facteur de stress souvent lié à la dynamique familiale (thérapie systémique)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · <span class=\"kw-ttt\">Activité physique adaptée</span></h4>\n      <p><strong>Indication :</strong> tableaux dominés par la <span class=\"kw-clinique\">fatigue</span> et/ou la <span class=\"kw-clinique\">douleur</span> (fibromyalgie, <span class=\"kw-clinique\">syndrome de fatigue</span> chronique, SII douloureux…).</p>\n      <ul>\n        <li><strong>Modalités :</strong> en <em>douceur</em> mais avec <em>régularité</em>, malgré une motivation souvent médiocre des patients ;</li>\n        <li><strong><span class=\"kw-chiffre\">1ère intention</span> :</strong>\n          <ul>\n            <li><span class=\"kw-ttt\"><strong>Tai Chi</strong></span> — efficacité démontrée dans plusieurs TSSA ⭐ ;</li>\n            <li>Qi Gong, Yoga, Marche nordique, Natation.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3 · Stratégies relationnelles et de réinsertion</h4>\n      <ul>\n        <li><strong>Soutien social</strong> — trouver de nouveaux modes d'interactions sociales permettant au patient d'obtenir du soutien sans faire intervenir <span class=\"kw-clinique\">les</span> symptômes et le statut de malade (= prise en charge des <span class=\"kw-clinique\">bénéfices secondaires</span>) ;</li>\n        <li><strong>Pour la famille</strong> (enfant/ado) — aide à communiquer sur <span class=\"kw-clinique\">les</span> facteurs de stress et à y faire face.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques</em></p>","frequence":1},{"id":"72-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications et non-indications des médicaments psychotropes","contenu":"<div class=\"callout callout-info\">\n        <strong>Règle générale.</strong> <span class=\"kw-clinique\">Les</span> psychotropes ont une <span class=\"kw-clinique\">place limitée</span> dans les TSSA. Aucun n'est curatif. Toujours associés à une psychothérapie (TCC ++) et à des stratégies non médicamenteuses.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Non-indications (médicaments inefficaces)</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Évaluation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Médicaments symptomatiques</strong></span> — <span class=\"kw-ttt\">antalgiques</span>, antispasmodiques</td>\n            <td><span class=\"kw-alerte\">Inefficaces dans les TSSA</span> — pourtant fréquemment prescrits par errance diagnostique ou pression du patient</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · Indications limitées (efficacité modeste)</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Indications spécifiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>ISRS</strong></span> (inhibiteurs sélectifs de la recapture de la sérotonine)</td>\n            <td>\n              Efficacité <span class=\"kw-clinique\">modeste</span> dans :<br>\n              <strong>Syndromes fonctionnels intestinaux</strong> (SII) ;<br>\n              <strong>Crainte excessive d'avoir une maladie</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>IRSNA</strong></span> (inhibiteurs de recapture sérotonine-noradrénaline)</td>\n            <td>\n              Peuvent soulager certains TSS avec <span class=\"kw-clinique\">douleur prédominante</span> :<br>\n              <strong>Fibromyalgie</strong> (ex. <span class=\"kw-ttt\">duloxétine</span>, milnacipran) ;<br>\n              Autres syndromes douloureux fonctionnels.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">3 · Autres psychotropes — selon <span class=\"kw-def\">comorbidité</span> psychiatrique</h4>\n      <p>En cas de <span class=\"kw-def\">comorbidité</span> psychiatrique avérée (EDC, trouble anxieux caractérisé, ESPT), <span class=\"kw-clinique\">les</span> psychotropes correspondants sont indiqués sur leur indication propre (pas sur le TSSA).</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠ Vigilance EI chez <span class=\"kw-clinique\">les</span> patients TSSA.</strong> <span class=\"kw-alerte\">Propension accrue aux effets indésirables</span>. Stratégie d'introduction :\n        <ul style=\"margin:6px 0 0;\">\n          <li><strong>Posologie initiale réduite</strong> (parfois la moitié de la dose habituelle) ;</li>\n          <li><strong>Titration lente</strong> ;</li>\n          <li><strong><span class=\"kw-def\">Éducation thérapeutique</span> renforcée</strong> sur <span class=\"kw-clinique\">les</span> EI attendus et leur <span class=\"kw-clinique\">évolution</span> ;</li>\n          <li><strong><span class=\"kw-def\">Réévaluation</span> rapprochée</strong> (efficacité + tolérance) ;</li>\n          <li>Si arrêt nécessaire : <strong>décroissance progressive</strong> (risque d'effet rebond).</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes · 66 — Trouble anxieux</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Pas d'<span class=\"kw-alerte\">urgence</span> vitale :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">TSSA</span> sont des troubles <span class=\"kw-clinique\">chroniques</span> ; l'<span class=\"kw-alerte\">hospitalisation</span> est en général non nécessaire.<br><strong>Enjeu temporel :</strong> éviter l'<span class=\"kw-alerte\">errance diagnostique</span> et la <span class=\"kw-alerte\">multiplication des examens complémentaires</span> qui pérennisent le trouble.<br><strong>Hospitalisation en psychiatrie :</strong> peut être nécessaire en cas de <span class=\"kw-alerte\">comorbidité psychiatrique avec signes de gravité</span>.</p>","hospit":"<p><strong>Principe :</strong> <span class=\"kw-alerte\">hospitalisation</span> <span class=\"kw-clinique\">en général non nécessaire</span> ; PEC <span class=\"kw-clinique\">ambulatoire</span> coordonnée par un <span class=\"kw-def\">médecin référent</span> (<span class=\"kw-chiffre\">1ère ligne</span>, non psychiatre).<br><strong>Hospitalisation courte en médecine :</strong> parfois indiquée pour réaliser <span class=\"kw-clinique\">les</span> examens éliminant un <span class=\"kw-etio\">diagnostic différentiel de pathologie médicale non psychiatrique</span>.<br><strong>Hospitalisation en psychiatrie :</strong> peut être nécessaire en cas de <span class=\"kw-alerte\">comorbidité psychiatrique avec signes de gravité</span>.<br><strong>Enfant / adolescent :</strong> exploration médicale non psychiatrique pour éliminer les DD, puis relais <span class=\"kw-clinique\">pédopsychiatrique</span> (<span class=\"kw-def\">comorbidités</span>, limiter les facteurs de maintenance et les bénéfices secondaires).<br><strong>Avis psychiatrique :</strong> en cas de <span class=\"kw-def\">comorbidité</span> (<span class=\"kw-etio\">EDC</span>, <span class=\"kw-etio\">trouble anxieux</span>, <span class=\"kw-etio\">ESPT</span>, <span class=\"kw-etio\">trouble de la personnalité</span>) ou de TSSA chroniques / réfractaires.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Comorbidité psychiatrique avec signes de gravité</span> → l'<span class=\"kw-alerte\">hospitalisation</span> en psychiatrie peut être nécessaire</li><li>Clinique évocatrice d'une <span class=\"kw-etio\">pathologie médicale non psychiatrique</span> sous-jacente → éliminer un <span class=\"kw-def\">diagnostic différentiel</span> organique (sans multiplier <span class=\"kw-clinique\">les</span> examens)</li><li><span class=\"kw-def\">Diagnostic différentiel</span> avec un <span class=\"kw-etio\">trouble psychotique</span> : <span class=\"kw-clinique\">sensations corporelles hallucinatoires</span>, <span class=\"kw-clinique\">idées délirantes hypocondriaques</span></li><li><span class=\"kw-def\">Comorbidité</span> psychiatrique caractérisée : <span class=\"kw-etio\">épisode dépressif</span>, <span class=\"kw-etio\">trouble anxieux caractérisé</span>, <span class=\"kw-etio\">ESPT</span>, <span class=\"kw-etio\">trouble de la personnalité</span> → avis psychiatrique</li><li><span class=\"kw-alerte\">TSSA chroniques ou réfractaires</span> → orienter vers un praticien expérimenté</li></ul>","principes":"<p><strong>Objectif prioritaire :</strong> maintenir une <span class=\"kw-def\">alliance thérapeutique de qualité</span>.<br><strong>Pilier :</strong> thérapeutiques <span class=\"kw-ttt\">non médicamenteuses</span> — <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">médicaments symptomatiques sont inefficaces</span>.</p><p><strong>Alliance & communication du diagnostic</strong></p><p>Ne jamais dire <span class=\"kw-ci\">« vous n'avez rien »</span> ni <span class=\"kw-ci\">« c'est dans la tête »</span></p><ul><li>Reconnaître que <span class=\"kw-clinique\">les</span> symptômes sont « véritables », effrayants et invalidants</li><li>Poser un <span class=\"kw-def\">diagnostic positif</span> (« troubles fonctionnels », souvent bien acceptés) — <span class=\"kw-alerte\">jamais par élimination</span></li><li>Exposer un <span class=\"kw-clinique\">modèle explicatif</span> des facteurs déclenchants et de maintien, même schématique</li></ul><p><strong>Examens complémentaires</strong></p><p>« Si le patient n'était pas si inquiet, est-ce que je prescrirais cet examen ? »</p><ul><li>Objectif : éliminer une <span class=\"kw-etio\">pathologie médicale non psychiatrique</span>, selon la clinique</li><li><span class=\"kw-alerte\">Ne pas multiplier les examens</span> : risque d'<span class=\"kw-clinique\">incidentalomes</span> et de renforcement des représentations du patient</li></ul><p><strong>Traitements <span class=\"kw-etio\">médicamenteux</span></strong></p><p><span class=\"kw-alerte\">Propension accrue aux effets indésirables</span> → débuter à faible posologie</p><ul><li><span class=\"kw-ttt\">Médicaments symptomatiques</span> (<span class=\"kw-ttt\">antalgiques</span>, antispasmodiques) : <span class=\"kw-alerte\">inefficaces</span></li><li><span class=\"kw-ttt\">ISRS</span> : efficacité modeste (syndromes fonctionnels intestinaux, crainte excessive d'avoir une maladie)</li><li><span class=\"kw-ttt\">IRSNA</span> : TSS avec <span class=\"kw-clinique\">douleur prédominante</span> (ex. fibromyalgie)</li></ul><p><strong>Psychothérapies (<span class=\"kw-chiffre\">1ère intention</span>)</strong></p><ul><li><span class=\"kw-ttt\">TCC</span> : plan cognitif (focalisation attentionnelle, catastrophisme) + plan comportemental (<span class=\"kw-clinique\">diminuer les conduites d'évitement par l'exposition</span>)</li><li>Compléments : pleine conscience, <span class=\"kw-ttt\">hypnose</span>, relaxation, <span class=\"kw-ttt\">biofeedback</span></li><li><span class=\"kw-ttt\">Thérapie familiale</span> chez l'<span class=\"kw-clinique\">enfant / adolescent</span> (facteur de stress lié à la dynamique familiale)</li></ul><p><strong>Activité physique</strong></p><ul><li>Indiquée dans <span class=\"kw-clinique\">les</span> tableaux dominés par la <span class=\"kw-clinique\">fatigue</span> et/ou la <span class=\"kw-clinique\">douleur</span></li><li>En douceur mais avec régularité, malgré une motivation souvent médiocre</li><li><span class=\"kw-chiffre\">1ère intention</span> : <span class=\"kw-ttt\">Tai Chi</span> (efficacité démontrée), Qi Gong, <span class=\"kw-ttt\">yoga</span>, marche nordique, natation</li></ul><p><strong>Coordination du <span class=\"kw-def\">suivi</span></strong></p><ul><li><span class=\"kw-def\">Médecin référent</span> indispensable pour limiter la répétition des examens</li><li>Transmettre l'hypothèse diagnostique et <span class=\"kw-clinique\">les</span> préconisations dans un <span class=\"kw-clinique\">courrier synthétique</span></li><li>Objectifs thérapeutiques <span class=\"kw-clinique\">modestes et atteignables</span> (atténuation des symptômes plutôt que guérison)</li></ul>","suivi":"<p><strong>Coordination :</strong> assurée par le <span class=\"kw-def\">médecin référent</span> ; transmission de l'hypothèse diagnostique et des préconisations dans un <span class=\"kw-clinique\">courrier synthétique</span>.<br><strong>Alliance thérapeutique :</strong> négocier <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">objectifs ET les moyens</span> de la thérapie ; objectifs modestes centrés sur l'atténuation des symptômes plutôt que sur la guérison.<br><strong>Expertise ponctuelle :</strong> spécialiste de l'appareil désigné ou <span class=\"kw-clinique\">interniste</span>, pour arbitrer la poursuite ou non des explorations.<br><strong><span class=\"kw-def\">Réévaluation</span> :</strong> orienter les <span class=\"kw-alerte\">TSSA chroniques ou réfractaires</span> vers un praticien expérimenté ; résolution complète parfois observée si le trouble est récent.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Plainte somatique chronique, pénible et invalidante — Sans anomalie d'organe proportionnée — médecin de 1ère ligne (non psychiatre)","detail":"<h4>CAT — orientation devant un trouble à symptomatologie somatique (TSSA) — Éliminer <span class=\"kw-clinique\">les</span> diagnostics différentiels, poser un <span class=\"kw-def\">diagnostic positif</span>, repérer une <span class=\"kw-def\">comorbidité</span> psychiatrique et organiser une PEC ambulatoire coordonnée</h4>","branches":[{"to":"q-dd","label":"Plainte légitime — démarche d'orientation par le médecin référent","color":"green"}]},{"id":"q-dd","kind":"decision","label":"Éliminer un diagnostic différentiel — Selon la clinique, sans multiplier les examens complémentaires","branches":[{"to":"t-hospit-med","label":"Clinique évocatrice d'une pathologie médicale non psychiatrique","color":"amber"},{"to":"t-dd-psy","label":"Plaintes somatiques d'allure psychiatrique (trouble psychotique, EDC, trouble anxieux)","color":"blue"},{"to":"q-gravite","label":"DD écartés — diagnostic positif de TSSA retenu","color":"green"}]},{"id":"t-hospit-med","kind":"terminal","label":"Explorations ciblées ± hospitalisation courte en médecine","color":"amber","detail":"<h4>Objectif</h4><ul><li>Éliminer une <span class=\"kw-etio\">pathologie médicale non psychiatrique</span> selon la clinique</li><li><span class=\"kw-alerte\">Hospitalisation</span> <span class=\"kw-clinique\">courte en médecine</span> parfois indiquée pour réaliser <span class=\"kw-clinique\">les</span> examens éliminant le <span class=\"kw-def\">diagnostic différentiel</span></li></ul><h4>Précautions</h4><ul><li>Cibler <span class=\"kw-clinique\">les</span> examens utiles et <span class=\"kw-alerte\">savoir les limiter</span></li><li><span class=\"kw-alerte\">Ne pas multiplier les examens</span> : risque d'<span class=\"kw-clinique\">incidentalomes</span> et de renforcement des représentations du patient</li></ul>"},{"id":"t-dd-psy","kind":"terminal","label":"Diagnostic différentiel psychiatrique à préciser","color":"blue","detail":"<h4>Tableaux à distinguer</h4><ul><li><span class=\"kw-etio\">Trouble psychotique</span> : <span class=\"kw-clinique\">sensations corporelles hallucinatoires</span>, <span class=\"kw-clinique\">idées délirantes hypocondriaques</span></li><li><span class=\"kw-etio\">Épisode dépressif caractérisé</span> : la douleur disparaît avec le syndrome dépressif</li><li><span class=\"kw-etio\">Troubles anxieux</span> : manifestations neurovégétatives (trouble panique ++)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Avis psychiatrique</span> pour préciser le diagnostic</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Comorbidité psychiatrique ? — Recherche d'un EDC, d'un trouble anxieux caractérisé, d'un ESPT ou d'un trouble de la personnalité","branches":[{"to":"t-hospit-psy","label":"Comorbidité psychiatrique avec signes de gravité","color":"red"},{"to":"t-avis-psy","label":"Comorbidité psychiatrique sans signe de gravité","color":"amber"},{"to":"t-ambulatoire","label":"Pas de comorbidité — TSSA isolé","color":"green"}]},{"id":"t-hospit-psy","kind":"terminal","label":"Hospitalisation en psychiatrie","color":"red","detail":"<h4>Indication</h4><ul><li>L'<span class=\"kw-alerte\">hospitalisation</span> en psychiatrie peut être nécessaire en cas de <span class=\"kw-alerte\">comorbidité psychiatrique avec signes de gravité</span></li></ul><h4>À retenir</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> <span class=\"kw-clinique\">en général non nécessaire</span> dans <span class=\"kw-clinique\">les</span> TSSA</li><li>Chez l'enfant : relais en <span class=\"kw-clinique\">pédopsychiatrie</span> — recherche des <span class=\"kw-def\">comorbidités</span>, limiter <span class=\"kw-clinique\">les</span> facteurs de maintenance et les bénéfices secondaires</li></ul>"},{"id":"t-avis-psy","kind":"terminal","label":"Avis psychiatrique + PEC ambulatoire coordonnée","color":"amber","detail":"<h4>Indications de l'évaluation psychiatrique</h4><ul><li><span class=\"kw-etio\">Épisode dépressif caractérisé</span>, <span class=\"kw-etio\">trouble anxieux caractérisé</span>, <span class=\"kw-etio\">ESPT</span>, <span class=\"kw-etio\">trouble de la personnalité</span></li><li><span class=\"kw-alerte\">TSSA chroniques ou réfractaires</span> → orienter vers un praticien expérimenté</li></ul><h4>Cadre</h4><ul><li>PEC <span class=\"kw-clinique\">ambulatoire coordonnée</span> par le médecin référent</li><li>Maintien de l'<span class=\"kw-def\">alliance thérapeutique</span></li></ul>"},{"id":"t-ambulatoire","kind":"terminal","label":"PEC ambulatoire coordonnée (TSSA isolé)","color":"green","detail":"<h4>Alliance & <span class=\"kw-def\">diagnostic positif</span></h4><ul><li>Reconnaître que <span class=\"kw-clinique\">les</span> symptômes sont « véritables », effrayants et invalidants</li><li>Poser un <span class=\"kw-def\">diagnostic positif</span> (« troubles fonctionnels ») — jamais par élimination</li><li><span class=\"kw-ci\">Ne jamais dire « vous n'avez rien » ni « c'est dans la tête »</span></li></ul><h4>Thérapeutiques (pilier non <span class=\"kw-etio\">médicamenteux</span>)</h4><ul><li><span class=\"kw-ttt\">TCC</span> en <span class=\"kw-chiffre\">1ère intention</span> ; approches psycho-corporelles (<span class=\"kw-ttt\">hypnose</span>, relaxation, <span class=\"kw-ttt\">biofeedback</span>)</li><li>Activité physique douce et régulière : <span class=\"kw-ttt\">Tai Chi</span>, Qi Gong, <span class=\"kw-ttt\">yoga</span>, marche nordique, natation</li><li><span class=\"kw-ttt\">Médicaments symptomatiques inefficaces</span> ; <span class=\"kw-ttt\">ISRS</span> / IRSNA d'efficacité modeste (douleur prédominante)</li></ul><h4>Coordination</h4><ul><li><span class=\"kw-def\">Médecin référent</span> indispensable — courrier synthétique, limiter la répétition des examens</li></ul>"}]},"cards":[{"i":"039ce3a07640","n":72,"o":"72-1","u":"Définition","t":"Connaître la définition générale des troubles à symptomatologie somatique et apparentés","q":"Comment la Classification Internationale des Maladies (CIM-11) définit-elle une entité similaire aux TSSA ?","a":"<p>La CIM-11 a retenu une entité unique nommée le <strong>Syndrome de Détresse Corporelle</strong> (<em>Bodily Distress Syndrome</em>), défini par la présence de <strong>&ge; 3 symptômes</strong> appartenant à <strong>&ge; 1 groupe</strong> parmi quatre (tension musculo-squelettique, symptômes généraux, activation neurovégétative cardiovasculaire, activation gastro-intestinale), entraînant un <strong>handicap significatif</strong>, après exclusion des diagnostics différentiels pertinents.</p>"},{"i":"98ed89fb1e96","n":72,"o":"72-1","u":"Définition","t":"Connaître la définition générale des troubles à symptomatologie somatique et apparentés","q":"Quel est le critère majeur différenciant les TSSA des anciens troubles somatoformes du DSM-IV ?","a":"<p>Le <strong>critère décisif</strong> est que la sémiologie n'est plus définie négativement par l'absence d'explication médicale des symptômes. Au contraire, elle est définie positivement par la <strong>triade pensées / émotions / comportements</strong> qui accompagnent les manifestations physiques.</p>"},{"i":"cab53c2ceb8d","n":72,"o":"72-1","u":"Définition","t":"Connaître la définition générale des troubles à symptomatologie somatique et apparentés","q":"Quelle est la définition générale des Troubles à Symptomatologie Somatique et Apparentés (TSSA) selon le DSM-5 ?","a":"<p>Les TSSA sont caractérisés par la présence de <strong>symptômes physiques</strong> accompagnés de <strong>pensées</strong>, <strong>émotions</strong> (anxiété santé), ou <strong>comportements</strong> (consultations répétées) inadaptés et disproportionnés face aux préoccupations de santé. Ces troubles étaient auparavant appelés « troubles somatoformes » dans le DSM-IV.</p>"},{"i":"f930191f61b8","n":72,"o":"72-1","u":"Définition","t":"Connaître la définition générale des troubles à symptomatologie somatique et apparentés","q":"L'absence de maladie non psychiatrique pouvant expliquer les symptômes physiques est-elle un critère nécessaire pour diagnostiquer un TSSA ?","a":"<p>Non, l'<strong>absence de maladie non psychiatrique</strong> pouvant expliquer les symptômes physiques n'est <strong>PAS un critère nécessaire</strong> au diagnostic d'un TSSA. Les TSSA peuvent être comorbides avec un trouble médical non psychiatrique et même favorisés par celui-ci.</p>"},{"i":"34821c8d25d3","n":72,"o":"72-2","u":"Définition","t":"Connaître la définition de ce que ne sont pas les troubles à symptomatologie somatique et apparentés","q":"Comment les facteurs psychologiques influençant une autre affection médicale se distinguent-ils des troubles à symptomatologie somatique et apparentés ?","a":"<p>Il s'agit d'une pathologie médicale non psychiatrique avec une <strong>lésion identifiable</strong>, pour laquelle des facteurs psychologiques (notamment le <strong>stress</strong>) jouent un rôle prépondérant de déclencheur ou d'entretien.</p><p>Le discriminant clé est la <strong>présence d'une lésion organique</strong>, les facteurs psychologiques n'étant qu'un facteur d'entretien ou de déclenchement.</p>"},{"i":"92182dbab08f","n":72,"o":"72-2","u":"Définition","t":"Connaître la définition de ce que ne sont pas les troubles à symptomatologie somatique et apparentés","q":"Quelle est la définition de la simulation et en quoi diffère-t-elle du trouble factice et des troubles à symptomatologie somatique et apparentés ?","a":"<p>La simulation est la production intentionnelle de signes ou symptômes avec une <strong>motivation consciente externe</strong>. Cette motivation peut être, par exemple, échapper à des poursuites judiciaires, obtenir des drogues, des indemnités, une pension de retraite ou un arrêt de travail.</p><p>Le discriminant clé est le caractère <strong>intentionnel avec un bénéfice externe explicite</strong>, la distinguant ainsi du trouble factice (motivation interne inconsciente) et des TSSA (non intentionnel).</p>"},{"i":"ae5116a9da6f","n":72,"o":"72-2","u":"Définition","t":"Connaître la définition de ce que ne sont pas les troubles à symptomatologie somatique et apparentés","q":"Quelle est la définition du trouble factice (syndrome de Münchhausen) et en quoi se distingue-t-il des troubles à symptomatologie somatique et apparentés ?","a":"<p>Le trouble factice correspond à la production intentionnelle de signes ou symptômes physiques ou psychologiques, sans motivation externe évidente.</p><ul><li>Les modalités peuvent inclure : l'exagération ou l'invention de symptômes, la falsification de documents médicaux, l'ingestion de toxiques, ou l'inoculation volontaire de germes pathogènes.</li><li>Sa variante est le trouble factice par procuration, imposé à autrui.</li></ul><p>Le discriminant clé par rapport aux TSSA est la <strong>production intentionnelle sans bénéfice externe</strong>.</p>"},{"i":"d4cd6386b4a7","n":72,"o":"72-2","u":"Définition","t":"Connaître la définition de ce que ne sont pas les troubles à symptomatologie somatique et apparentés","q":"Quelle est la définition de la peur d'une dysmorphie corporelle (dysmorphophobie) et pourquoi n'est-elle pas classée parmi les troubles à symptomatologie somatique et apparentés ?","a":"<p>La peur d'une dysmorphie corporelle est caractérisée par des <strong>idées obsessionnelles</strong> concernant une imperfection ou des défauts dans l'apparence physique, et des <strong>compulsions</strong> (ex. vérifications devant un miroir, toilette interminable, arrachage de poils).</p><p>Elle n'est pas classée parmi les TSSA car elle fait partie des <strong>troubles obsessionnels-compulsifs (TOC)</strong> du DSM-5.</p>"},{"i":"8148acea5388","n":72,"o":"72-6","u":"Diagnostic positif","t":"Connaître la sémiologie des principaux troubles","q":"Quels sont les diagnostics différentiels majeurs des troubles à symptomatologie somatique et apparentés (TSSA) ?","a":"<p>Les diagnostics différentiels majeurs des TSSA incluent :</p><ul><li>Les <strong>pathologies médicales non psychiatriques</strong> : il est impératif de les éliminer cliniquement, sans multiplier les examens. La comorbidité entre TSSA et pathologies médicales est fréquente (ex: fibromyalgie et polyarthrite rhumatoïde).</li><li>Les <strong>troubles anxieux</strong> : principalement les troubles paniques, qui peuvent générer des plaintes somatiques par leurs manifestations neurovégétatives.</li><li>Les <strong>troubles psychotiques</strong> : peuvent se manifester par des sensations corporelles hallucinatoires ou des idées délirantes hypocondriaques.</li><li>Le <strong>trouble dépressif caractérisé (TDC ou EDC)</strong> : il peut présenter des plaintes douloureuses non systématisées. Le discriminant clé est que la douleur dans le TDC évolue parallèlement à l'humeur et disparaît avec le syndrome dépressif, contrairement aux TSSA.</li></ul>"},{"i":"8d833a7a64c6","n":72,"o":"72-6","u":"Diagnostic positif","t":"Connaître la sémiologie des principaux troubles","q":"Qu'est-ce que le trouble de conversion et quelles en sont ses particularités en termes de diagnostic ?","a":"<p>Le trouble de conversion (ou trouble à symptomatologie neurologique fonctionnelle) est défini par la présence de <strong>déficits moteurs ou sensoriels incompatibles avec la systématisation du système nerveux</strong>, mais suggérant la présence d'un trouble neurologique ou d'un autre trouble médical. Sa prévalence est de <strong>0,1 %</strong>.</p><p>Ses particularités diagnostiques sont :</p><ul><li>Les <strong>facteurs de stress</strong> peuvent être retrouvés mais ne sont pas obligatoires. Leur absence n'élimine pas le diagnostic.</li><li>La triade « pensées / émotions / comportements » est <strong>moins présente</strong> que dans les autres TSSA.</li><li>Les <strong>mécanismes de dissociation</strong>, tels que l'amnésie dissociative, la déréalisation ou la dépersonnalisation, sont fréquemment associés et impliqués dans la physiopathologie.</li><li>Les <strong>explorations neurologiques</strong> (examen clinique, EEG en cas de crises) mettent en évidence l'incompatibilité de la sémiologie avec une maladie neurologique, par exemple une absence d'activité épileptiforme pour les crises non épileptiques psychogènes.</li></ul>"},{"i":"a1a4d63a8e1f","n":72,"o":"72-6","u":"Diagnostic positif","t":"Connaître la sémiologie des principaux troubles","q":"Comment définit-on le trouble à symptomatologie somatique (TSS) et quelles sont ses manifestations ?","a":"<p>Le trouble à symptomatologie somatique (TSS) se caractérise par des symptômes physiques dérangeants ou invalidants, associés à des pensées, des émotions et des comportements excessifs ou disproportionnés liés à ces symptômes. La prévalence est de <strong>5 à 7 %</strong>.</p><ul><li><strong>Pensées :</strong> anticipation des conséquences interprétées comme potentiellement catastrophiques.</li><li><strong>Émotions anxieuses :</strong> soucis, préoccupations, inquiétudes sur la santé.</li><li><strong>Comportements :</strong> consultations médicales répétées, vérifications corporelles systématiques, recherche excessive d'information.</li></ul><p>Ces manifestations sont centrées sur des signes/symptômes physiques mésinterprétés comme une pathologie grave. Un spécificateur « avec douleur prédominante » peut être ajouté.</p>"},{"i":"bf3b4b811f21","n":72,"o":"72-6","u":"Diagnostic positif","t":"Connaître la sémiologie des principaux troubles","q":"Comment différencie-t-on la crainte excessive d'avoir une maladie du trouble à symptomatologie somatique (TSS) ?","a":"<p>La crainte excessive d'avoir une maladie (prévalence <strong>3 à 8 %</strong>) partage les mêmes manifestations que le TSS en termes de pensées (catastrophisation), d'émotions (anxiété de santé) et de comportements (recherche de réassurance). Cependant, la différence essentielle est l'<strong>absence de signes ou symptômes physiques pénibles ou invalidants par eux-mêmes</strong>. Les tentatives de réassurance médicale sont inefficaces et la durée des manifestations doit être <strong>supérieure à 6 mois</strong>.</p>"},{"i":"6d29ae22ea5d","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quels sont les trois piliers essentiels à respecter lors de l'annonce diagnostique des Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>Les trois piliers essentiels de la stratégie de communication du diagnostic sont :</p><ul><li><strong>Reconnaître les symptômes comme « véritables »</strong> : reconnaître la pénibilité, le retentissement et le caractère non volontaire des troubles, sans disqualifier le parcours antérieur. Ne jamais dire « vous n'avez rien » ou « c'est dans la tête ».</li><li><strong>Proposer un diagnostic POSITIF</strong> : utiliser des termes comme « troubles fonctionnels » souvent bien acceptés, et expliquer qu'il s'agit d'une maladie commune et reconnue. Éviter le diagnostic par élimination.</li><li><strong>Évoquer les facteurs déclenchants et de maintien</strong> : exposer un modèle explicatif, même schématique, de la survenue et de la pérennisation des symptômes pour crédibiliser les propositions thérapeutiques.</li></ul>"},{"i":"77b8870a7837","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Comment doit être orientée la prise en charge initiale des Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>La prise en charge initiale est principalement <strong>ambulatoire</strong>, coordonnée par un <strong>médecin référent</strong>. L'hospitalisation est rarement nécessaire, sauf dans les situations suivantes :</p><ul><li><strong>Médecine courte</strong> : pour éliminer un diagnostic différentiel de pathologie médicale non psychiatrique.</li><li><strong>Psychiatrie</strong> : en cas de comorbidité psychiatrique avec signes de gravité.</li><li><strong>Pédopsychiatrie</strong> : pour une exploration médicale ciblée et une prise en charge pédopsychiatrique, avec recherche des comorbidités et limitation des bénéfices secondaires.</li></ul>"},{"i":"94cc226258f8","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quel est le principe prioritaire et fondamental de la prise en charge des Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>Le principe prioritaire et fondamental est de <strong>maintenir une alliance thérapeutique de qualité</strong>. C'est l'axe central sans lequel aucune prise en charge n'est possible, compte tenu du scepticisme ou de la réticence fréquents des patients à l'idée d'une participation psychologique à leurs symptômes.</p>"},{"i":"acf389ad459d","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quelles sont les psychothérapies à privilégier et les techniques complémentaires efficaces dans les Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>La <strong>TCC (Thérapie Cognitivo-Comportementale)</strong> est le traitement de <strong>première intention</strong>, avec une efficacité démontrée. Elle agit sur :</p><ul><li>Le plan cognitif : prise de conscience de la focalisation sur les sensations corporelles et du catastrophisme.</li><li>Le plan comportemental : identification et diminution des conduites d'évitement par l'exposition.</li></ul><p>Les techniques complémentaires incluent :</p><ul><li>L'<strong>entraînement attentionnel</strong> et les <strong>thérapies basées sur la pleine conscience</strong>.</li><li>Les <strong>approches psycho-corporelles</strong> comme la relaxation, la sophrologie, l'hypnose, la méditation pleine conscience.</li><li>Les <strong>exercices de relaxation</strong> (respiratoires, baisse de la tension musculaire, biofeedback).</li><li>La <strong>thérapie familiale</strong> chez l'enfant/adolescent lorsque le stress est lié à la dynamique familiale.</li></ul>"},{"i":"c8adec5962ba","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quelle est la place des examens complémentaires dans la prise en charge des Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>L'objectif initial des examens complémentaires est d'<strong>éliminer une pathologie médicale non psychiatrique</strong>. Cependant, il faut être vigilant quant à la <strong>prescription excessive</strong> qui peut pérenniser le trouble en :</p><ul><li>Révélant des <strong>incidentalomes</strong>, conduisant à des explorations et traitements inutiles.</li><li>Renforçant des représentations du patient comme « les médecins ne savent pas ce que j'ai ».</li></ul><p>Une question clé pour le clinicien est : « Si le patient n'était pas si inquiet, est-ce que je prescrirais cet examen ? » Si la réponse est non, l'examen ne doit pas être prescrit.</p>"},{"i":"d76054c3b4ce","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quels sont les traitements médicamenteux pertinents et leur efficacité dans les Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>Les traitements médicamenteux ont une efficacité limitée :</p><ul><li>Les <strong>médicaments symptomatiques</strong> (antalgiques, antispasmodiques) sont généralement <strong>inefficaces</strong>.</li><li>Les <strong>ISRS</strong> (Inhibiteurs Sélectifs de la Recapture de la Sérotonine) ont une <strong>efficacité modeste</strong> dans les syndromes fonctionnels intestinaux et la crainte excessive d'avoir une maladie.</li><li>Les <strong>IRSNA</strong> (Inhibiteurs de la Recapture de la Sérotonine et de la Noradrénaline) peuvent soulager certains TSSA avec douleur prédominante (ex. fibromyalgie).</li></ul><p>Une vigilance particulière est requise face aux <strong>effets indésirables</strong> : débuter à faible posologie, éducation thérapeutique renforcée, réévaluation rapprochée, en raison d'une propension accrue aux effets indésirables chez ces patients.</p>"},{"i":"dd2d86929726","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Comment organiser la coordination du suivi d'un patient présentant des Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>Une coordination rigoureuse du suivi est indispensable :</p><ul><li>Un <strong>médecin référent</strong> est primordial pour limiter la répétition des examens complémentaires.</li><li>Il doit <strong>transmettre l'hypothèse diagnostique et les préconisations</strong> à tous les intervenants via un courrier synthétique.</li><li>Le recours à l'<strong>expertise ponctuelle</strong> d'un spécialiste ou d'un interniste peut aider le référent à se concentrer sur la thérapeutique.</li><li>La <strong>construction de l'alliance</strong> passe par la négociation des objectifs et des moyens de la thérapie avec le patient.</li><li>Les <strong>objectifs thérapeutiques</strong> doivent être modestes et atteignables, visant l'<strong>atténuation des symptômes et de leur retentissement psychosocial</strong> plutôt que la guérison complète chez l'adulte.</li></ul>"},{"i":"e67245e4f00c","n":72,"o":"72-7","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quelle est l'importance de l'activité physique et ses modalités dans la prise en charge des Troubles à Symptomatologie Somatique et Apparentés (TSSA) ?","a":"<p>La promotion de l'activité physique est <strong>essentielle</strong>, surtout dans les TSSA dominés par la fatigue et/ou la douleur. Les modalités doivent être :</p><ul><li><strong>En douceur mais avec régularité</strong>, malgré la motivation souvent médiocre des patients.</li><li>Les activités de première intention comprennent le <strong>Tai Chi</strong> (efficacité démontrée dans plusieurs TSSA), le Qi Gong, le Yoga, la marche nordique et la natation.</li></ul>"}]};